package store

import (
	"path/filepath"
	"testing"
	"time"
)

func openAt(t *testing.T, now time.Time) *Store {
	t.Helper()
	current := now
	st, err := OpenWithClock(filepath.Join(t.TempDir(), "store.db"), func() time.Time {
		return current
	})
	if err != nil {
		t.Fatalf("open: %v", err)
	}
	t.Cleanup(func() { st.Close() })
	st.now = func() time.Time { return current }
	st.setClock = func(tm time.Time) { current = tm }
	return st
}

